import{_ as p,a0 as n,w as l,s as d,ao as r,I as o,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何判斷 Linux 服務器是否被入侵？ | LCTT x X-CMD","titleTemplate":false,"description":"如何判斷 Linux 服務器是否被入侵？ | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何判斷 Linux 服務器是否被入侵？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何判斷 Linux 服務器是否被入侵？ | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171128 How To Tell If Your Linux Server Has Been Compromised","title":"如何判斷 Linux 服務器是否被入侵？","tag":"201712","desc":""},"relativePath":"201712/20171128 How To Tell If Your Linux Server Has Been Compromised.md","filePath":"[post].md"}'),h={name:"201712/20171128 How To Tell If Your Linux Server Has Been Compromised.md"};function c(u,e,g,k,b,f){const a=n("Link");return l(),d("div",null,[e[13]||(e[13]=r(`<h1 id="如何判斷-linux-服務器是否被入侵" tabindex="-1">如何判斷 Linux 服務器是否被入侵？ <a class="header-anchor" href="#如何判斷-linux-服務器是否被入侵" aria-label="Permalink to “如何判斷 Linux 服務器是否被入侵？”">​</a></h1><p>本指南中所謂的服務器被入侵或者説被黑了的意思，是指未經授權的人或程序為了自己的目的登錄到服務器上去並使用其計算資源，通常會產生不好的影響。</p><p>免責聲明：若你的服務器被類似 NSA 這樣的國家機關或者某個犯罪集團入侵，那麼你並不會注意到有任何問題，這些技術也無法發覺他們的存在。</p><p>然而，大多數被攻破的服務器都是被類似自動攻擊程序這樣的程序或者類似“腳本小子”這樣的廉價攻擊者，以及蠢蛋罪犯所入侵的。</p><p>這類攻擊者會在訪問服務器的同時濫用服務器資源，並且不怎麼會採取措施來隱藏他們正在做的事情。</p><h3 id="被入侵服務器的症狀" tabindex="-1">被入侵服務器的症狀 <a class="header-anchor" href="#被入侵服務器的症狀" aria-label="Permalink to “被入侵服務器的症狀”">​</a></h3><p>當服務器被沒有經驗攻擊者或者自動攻擊程序入侵了的話，他們往往會消耗 100% 的資源。他們可能消耗 CPU 資源來進行數字貨幣的採礦或者發送垃圾郵件，也可能消耗帶寬來發動 DoS 攻擊。</p><p>因此出現問題的第一個表現就是服務器 “變慢了”。這可能表現在網站的頁面打開的很慢，或者電子郵件要花很長時間才能發送出去。</p><p>那麼你應該查看那些東西呢?</p><h4 id="檢查-1-當前都有誰在登錄" tabindex="-1">檢查 1 - 當前都有誰在登錄? <a class="header-anchor" href="#檢查-1-當前都有誰在登錄" aria-label="Permalink to “檢查 1 - 當前都有誰在登錄?”">​</a></h4><p>你首先要查看當前都有誰登錄在服務器上。發現攻擊者登錄到服務器上進行操作並不複雜。</p><p>其對應的命令是 <code>w</code>。運行 <code>w</code> 會輸出如下結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 08:32:55 up 98 days,  5:43,  2 users,  load average: 0.05, 0.03, 0.00</span></span>
<span class="line"><span>USER     TTY      FROM             LOGIN@   IDLE   JCPU   PCPU WHAT</span></span>
<span class="line"><span>root     pts/0    113.174.161.1    08:26    0.00s  0.03s  0.02s ssh root@coopeaa12</span></span>
<span class="line"><span>root     pts/1    78.31.109.1      08:26    0.00s  0.01s  0.00s w</span></span></code></pre></div><p>第一個 IP 是英國 IP，而第二個 IP 是越南 IP。這個不是個好兆頭。</p><p>停下來做個深呼吸, 不要恐慌之下只是幹掉他們的 SSH 連接。除非你能夠防止他們再次進入服務器，否則他們會很快進來並踢掉你，以防你再次回去。</p><p>請參閲本文最後的“被入侵之後怎麼辦”這一章節來看找到了被入侵的證據後應該怎麼辦。</p><p><code>whois</code> 命令可以接一個 IP 地址然後告訴你該 IP 所註冊的組織的所有信息，當然就包括所在國家的信息。</p><h4 id="檢查-2-誰曾經登錄過" tabindex="-1">檢查 2 - 誰曾經登錄過? <a class="header-anchor" href="#檢查-2-誰曾經登錄過" aria-label="Permalink to “檢查 2 - 誰曾經登錄過?”">​</a></h4><p>Linux 服務器會記錄下哪些用户，從哪個 IP，在什麼時候登錄的以及登錄了多長時間這些信息。使用 <code>last</code> 命令可以查看這些信息。</p><p>輸出類似這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root     pts/1        78.31.109.1      Thu Nov 30 08:26   still logged in</span></span>
<span class="line"><span>root     pts/0        113.174.161.1    Thu Nov 30 08:26   still logged in</span></span>
<span class="line"><span>root     pts/1        78.31.109.1      Thu Nov 30 08:24 - 08:26  (00:01)</span></span>
<span class="line"><span>root     pts/0        113.174.161.1    Wed Nov 29 12:34 - 12:52  (00:18)</span></span>
<span class="line"><span>root     pts/0        14.176.196.1     Mon Nov 27 13:32 - 13:53  (00:21)</span></span></code></pre></div><p>這裏可以看到英國 IP 和越南 IP 交替出現，而且最上面兩個 IP 現在還處於登錄狀態。如果你看到任何未經授權的 IP，那麼請參閲最後章節。</p><p>登錄後的歷史記錄會記錄到二進制的 <code>/var/log/wtmp</code> 文件中（LCTT 譯註：這裏作者應該寫錯了，根據實際情況修改），因此很容易被刪除。通常攻擊者會直接把這個文件刪掉，以掩蓋他們的攻擊行為。 因此, 若你運行了 <code>last</code> 命令卻只看得見你的當前登錄，那麼這就是個不妙的信號。</p><p>如果沒有登錄歷史的話，請一定小心，繼續留意入侵的其他線索。</p><h4 id="檢查-3-回顧命令歷史" tabindex="-1">檢查 3 - 回顧命令歷史 <a class="header-anchor" href="#檢查-3-回顧命令歷史" aria-label="Permalink to “檢查 3 - 回顧命令歷史”">​</a></h4><p>這個層次的攻擊者通常不會注意掩蓋命令的歷史記錄，因此運行 <code>history</code> 命令會顯示出他們曾經做過的所有事情。 一定留意有沒有用 <code>wget</code> 或 <code>curl</code> 命令來下載類似垃圾郵件機器人或者挖礦程序之類的非常規軟件。</p><p>命令歷史存儲在 <code>~/.bash_history</code> 文件中，因此有些攻擊者會刪除該文件以掩蓋他們的所作所為。跟登錄歷史一樣，若你運行 <code>history</code> 命令卻沒有輸出任何東西那就表示歷史文件被刪掉了。這也是個不妙的信號，你需要很小心地檢查一下服務器了。（LCTT 譯註，如果沒有命令歷史，也有可能是你的配置錯誤。）</p><h4 id="檢查-4-哪些進程在消耗-cpu" tabindex="-1">檢查 4 - 哪些進程在消耗 CPU？ <a class="header-anchor" href="#檢查-4-哪些進程在消耗-cpu" aria-label="Permalink to “檢查 4 - 哪些進程在消耗 CPU？”">​</a></h4><p>你常遇到的這類攻擊者通常不怎麼會去掩蓋他們做的事情。他們會運行一些特別消耗 CPU 的進程。這就很容易發現這些進程了。只需要運行 <code>top</code> 然後看最前的那幾個進程就行了。</p><p>這也能顯示出那些未登錄進來的攻擊者。比如，可能有人在用未受保護的郵件腳本來發送垃圾郵件。</p><p>如果你最上面的進程對不瞭解，那麼你可以 Google 一下進程名稱，或者通過 <code>losf</code> 和 <code>strace</code> 來看看它做的事情是什麼。</p><p>使用這些工具，第一步從 <code>top</code> 中拷貝出進程的 PID，然後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -p PID</span></span></code></pre></div><p>這會顯示出該進程調用的所有系統調用。它產生的內容會很多，但這些信息能告訴你這個進程在做什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsof  -p PID</span></span></code></pre></div><p>這個程序會列出該進程打開的文件。通過查看它訪問的文件可以很好的理解它在做的事情。</p><h4 id="檢查-5-檢查所有的系統進程" tabindex="-1">檢查 5 - 檢查所有的系統進程 <a class="header-anchor" href="#檢查-5-檢查所有的系統進程" aria-label="Permalink to “檢查 5 - 檢查所有的系統進程”">​</a></h4><p>消耗 CPU 不嚴重的未授權進程可能不會在 <code>top</code> 中顯露出來，不過它依然可以通過 <code>ps</code> 列出來。命令 <code>ps auxf</code> 就能顯示足夠清晰的信息了。</p><p>你需要檢查一下每個不認識的進程。經常運行 <code>ps</code> （這是個好習慣）能幫助你發現奇怪的進程。</p><h4 id="檢查-6-檢查進程的網絡使用情況" tabindex="-1">檢查 6 - 檢查進程的網絡使用情況 <a class="header-anchor" href="#檢查-6-檢查進程的網絡使用情況" aria-label="Permalink to “檢查 6 - 檢查進程的網絡使用情況”">​</a></h4><p><code>iftop</code> 的功能類似 <code>top</code>，它會排列顯示收發網絡數據的進程以及它們的源地址和目的地址。類似 DoS 攻擊或垃圾機器人這樣的進程很容易顯示在列表的最頂端。</p><h4 id="檢查-7-哪些進程在監聽網絡連接" tabindex="-1">檢查 7 - 哪些進程在監聽網絡連接? <a class="header-anchor" href="#檢查-7-哪些進程在監聽網絡連接" aria-label="Permalink to “檢查 7 - 哪些進程在監聽網絡連接?”">​</a></h4><p>通常攻擊者會安裝一個後門程序專門監聽網絡端口接受指令。該進程等待期間是不會消耗 CPU 和帶寬的，因此也就不容易通過 <code>top</code> 之類的命令發現。</p><p><code>lsof</code> 和 <code>netstat</code> 命令都會列出所有的聯網進程。我通常會讓它們帶上下面這些參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsof -i</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>netstat -plunt</span></span></code></pre></div><p>你需要留意那些處於 <code>LISTEN</code> 和 <code>ESTABLISHED</code> 狀態的進程，這些進程要麼正在等待連接（LISTEN），要麼已經連接（ESTABLISHED）。如果遇到不認識的進程，使用 <code>strace</code> 和 <code>lsof</code> 來看看它們在做什麼東西。</p><h3 id="被入侵之後該怎麼辦呢" tabindex="-1">被入侵之後該怎麼辦呢? <a class="header-anchor" href="#被入侵之後該怎麼辦呢" aria-label="Permalink to “被入侵之後該怎麼辦呢?”">​</a></h3><p>首先，不要緊張，尤其當攻擊者正處於登錄狀態時更不能緊張。<strong>你需要在攻擊者警覺到你已經發現他之前奪回機器的控制權。</strong>如果他發現你已經發覺到他了，那麼他可能會鎖死你不讓你登陸服務器，然後開始毀屍滅跡。</p><p>如果你技術不太好那麼就直接關機吧。你可以在服務器上運行 <code>shutdown -h now</code> 或者 <code>systemctl poweroff</code> 這兩條命令之一。也可以登錄主機提供商的控制面板中關閉服務器。關機後，你就可以開始配置防火牆或者諮詢一下供應商的意見。</p><p>如果你對自己頗有自信，而你的主機提供商也有提供上游防火牆，那麼你只需要以此創建並啓用下面兩條規則就行了：</p><ol><li>只允許從你的 IP 地址登錄 SSH。</li><li>封禁除此之外的任何東西，不僅僅是 SSH，還包括任何端口上的任何協議。</li></ol><p>這樣會立即關閉攻擊者的 SSH 會話，而只留下你可以訪問服務器。</p><p>如果你無法訪問上游防火牆，那麼你就需要在服務器本身創建並啓用這些防火牆策略，然後在防火牆規則起效後使用 <code>kill</code> 命令關閉攻擊者的 SSH 會話。（LCTT 譯註：本地防火牆規則 有可能不會阻止已經建立的 SSH 會話，所以保險起見，你需要手工殺死該會話。）</p><p>最後還有一種方法，如果支持的話，就是通過諸如串行控制台之類的帶外連接登錄服務器，然後通過 <code>systemctl stop network.service</code> 停止網絡功能。這會關閉所有服務器上的網絡連接，這樣你就可以慢慢的配置那些防火牆規則了。</p><p>重奪服務器的控制權後，也不要以為就萬事大吉了。</p><p>不要試着修復這台服務器，然後接着用。你永遠不知道攻擊者做過什麼，因此你也永遠無法保證這台服務器還是安全的。</p><p>最好的方法就是拷貝出所有的數據，然後重裝系統。（LCTT 譯註：你的程序這時已經不可信了，但是數據一般來説沒問題。）</p><hr>`,59)),o("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://bash-prompt.net/guides/server-hacked/"},{default:t(()=>[...e[0]||(e[0]=[s("https://bash-prompt.net/guides/server-hacked/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=s("作者：",-1)),i(a,{href:"https://bash-prompt.net"},{default:t(()=>[...e[2]||(e[2]=[s("Elliot Cooper",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const x=p(h,[["render",c]]);export{C as __pageData,x as default};
